import json

# Let's search the entire session log for any feedback like "correct" or "incorrect"
with open('/home/USER/runs/paper/qwen-h-in-glm-hpl-u1/frozen/seen-5/play/users/u075/system/state/sessions/01a1ab7b-0fab-72b6-bf08-5b2615f8d42d.jsonl', 'r') as f:
    content = f.read()

# Search for feedback keywords
keywords = ['correct', 'incorrect', 'task completed', 'task failed', 'feedback', 'success']
for kw in keywords:
    if kw.lower() in content.lower():
        print(f"Found '{kw}' in log")
        # Show context around it
        idx = content.lower().find(kw.lower())
        if idx >= 0:
            start = max(0, idx - 100)
            end = min(len(content), idx + 200)
            print(f"Context: {content[start:end]}")
    else:
        print(f"Did not find '{kw}'")

# Also check for submission patterns
if '"action": "submit"' in content:
    print("Found submit actions in log")
else:
    print("No submit actions found in log")
